UPDATE rbac_user
SET password_hash = #{passwordHash}
WHERE id = #{userId}

UPDATE rbac_user
SET password_hash = #{passwordHash}
WHERE username = #{username}

UPDATE rbac_user
SET login_fail_count = 0, last_login_time = CURRENT_TIMESTAMP
WHERE id = #{userId}

UPDATE rbac_user
SET login_fail_count = login_fail_count + 1
WHERE username = #{username}
